import{_ as e,o as t,b as S,q as a}from"./chunks/framework.Tf23FRXt.js";const m=JSON.parse('{"title":"避暑离宫马利卡大井","description":"","frontmatter":{},"headers":[{"level":2,"title":"进场 ~ BOSS 1","slug":"进场-boss-1","link":"#进场-boss-1","children":[{"level":3,"title":"BOSS 1 大犰狳","slug":"boss-1-大犰狳","link":"#boss-1-大犰狳","children":[]}]},{"level":2,"title":"BOSS 1 ~ BOSS 2","slug":"boss-1-boss-2","link":"#boss-1-boss-2","children":[{"level":3,"title":"BOSS 2 水陆两用塔罗斯","slug":"boss-2-水陆两用塔罗斯","link":"#boss-2-水陆两用塔罗斯","children":[]}]},{"level":2,"title":"BOSS 2 ~ BOSS 3","slug":"boss-2-boss-3","link":"#boss-2-boss-3","children":[{"level":3,"title":"BOSS 3 斯托尔戈","slug":"boss-3-斯托尔戈","link":"#boss-3-斯托尔戈","children":[]}]}],"relativePath":"duty/656.htm.md","filePath":"duty/656.md","lastUpdated":1791101830000}'),l={name:"duty/656.htm.md"};function i(o,s,r,d,n,b){return t(),S("div",null,[...s[0]||(s[0]=[a('<h1 id="避暑离宫马利卡大井" tabindex="-1">避暑离宫马利卡大井</h1><p>这是一个破败的地下宫殿，没什么特别的。</p><h2 id="进场-boss-1" tabindex="-1">进场～BOSS 1</h2><p>没有什么特别的</p><h3 id="boss-1-大犰狳" tabindex="-1">BOSS 1 大犰狳</h3><p><mark>大回旋</mark>和百吨回转一样是近身 360 度回转攻击，所有人远离躲避。<mark>重锤碎击</mark>需要先远离（距离衰减 AOE），再靠近（环形 AOE），同时伴有小 AOE，冷静躲避即可。</p><h2 id="boss-1-boss-2" tabindex="-1">BOSS 1 ~ BOSS 2</h2><p>还是没什么特别的</p><h3 id="boss-2-水陆两用塔罗斯" tabindex="-1">BOSS 2 水陆两用塔罗斯</h3><p>核心技能<mark>钻井</mark>，先远离躲避 AOE，之后场地四周会出现 4 个 AOE 预警圈，这 4 个圈会出现喷泉，紧接着<mark>高压</mark>全屏击退（防击退有效），需要找喷泉的缝隙躲避，避免被击退到水里。<mark>强制排水</mark>和 71 本老三机制接近，周身出现旋转箭头，一边使用范围技能一边旋转，躲在 BOSS 身后跟着它转即可安全回避。</p><h2 id="boss-2-boss-3" tabindex="-1">BOSS 2 ~ BOSS 3</h2><p>路上会遇到石碓读条<mark>重组</mark>，如果在读条结束前打倒的话，它就直接碎掉，如果读条结束，它就会站起来开始进攻… 但是这个石头人出来以后比较脆，打人也不是很疼，如果队伍中有 AOE 比较强的 DPS，可以考虑放它读条出来。</p><h3 id="boss-3-斯托尔戈" tabindex="-1">BOSS 3 斯托尔戈</h3><p>BOSS 读条<mark>异端十字叉</mark>，同时身边出现 4 个三角形白光，站在三角底边交点处（有发光白点）的地方即安全。<mark>碎轮</mark>地上有白灰似的一圈特效，站在 BOSS 圈内（脚下）安全。BOSS 召唤 4 个羽毛落在 BOSS 之后，四个羽毛和 BOSS 本体会轮流发动上述两个技能，先出现技能特效的分身会先放技能，注意观察好顺序，冷静寻找安全点（白点或脚下）即可突破。</p>',14)])])}const p=e(l,[["render",i]]);export{m as __pageData,p as default};
